cd /home/ubuntu/.agent-ml-research-idea_gen_0509_2/projects/ratekv && python3 -c "
import yaml
with open('registry.yaml') as f:
    reg = yaml.safe_load(f)
exps = reg.get('experiments', reg)
# Search for 32.45 or unconstrained greedy in any experiment
for k, v in exps.items():
    if isinstance(v, dict):
        s = str(v)
        if '32.45' in s or ('qwen' in k.lower() and 'unconstrained' in s.lower()):
            print(f'{k}:')
            print(f'  status={v.get(\"status\")}')
            m = v.get('metrics', {})
            if m:
                for mk, mv in m.items():
                    if 'greedy' in str(mk).lower() or 'unconstrained' in str(mk).lower() or '32' in str(mv):
                        print(f'  {mk}: {mv}')
            spec = v.get('spec', {})
            if spec:
                print(f'  eval_data: {spec.get(\"eval_data\", \"NOT SET\")}')
                print(f'  command: {str(spec.get(\"command\", \"NOT SET\"))[:100]}')
            print()
" 2>&1

